tools.exec_command({cmd:"python3 -B -m unittest discover -s tests -v","max_output_tokens":1200}),
tools.exec_command({cmd:"bash /home/mike/.codex/plugins/cache/fellowship-apprentice-workspace/apprentice-workspace/local/library/skills/scan-agent-skill/scripts/scan.sh skills/class-code-assistant > .runs/gate4/skill-scan-complete.md","yield_time_ms":1000,"max_output_tokens":500}),
tools.exec_command({cmd:"sed -n '47,90p' skills/class-code-assistant/scripts/reporting.py; rg -n 'labels|facts|_request' skills/class-code-assistant/scripts/reporting.py","max_output_tokens":2000})
]);r.forEach(text);

text(await tools.exec_command({cmd:"python3 -B skills/class-code-assistant/scripts/audit.py --bundle .runs/gate3/six-cases.json --output-dir .runs/gate4/complete-output","max_output_tokens":500}));
text(await tools.exec_command({cmd:"python3 -B - <<'PY'
from pathlib import Path
import json, shutil
old=Path('deliverables'); new=Path('.runs/gate4/complete-output')
for folder in ('codes','ledgers'):
 files=list((old/folder).iterdir()); assert len(files)==6
 for f in files: assert f.read_bytes()==(new/folder/f.name).read_bytes(),f
issues=[i for f in (new/'ledgers').glob('*.json') for i in json.loads(f.read_text())['issues']]
assert len(issues)==16 and all(i['status']=='open' and i['confirmations']==[] for i in issues)
assert sum(i['amount'] is None for i in issues if 'owner' in i['id'])==5
for f in new.rglob('*'):
 if f.is_file(): shutil.copyfile(f,old/f.relative_to(new))
sizes={f:(new/f).stat().st_size for f in ('audit-report.md','audit-questions.md','internal-decisions.md')}
print('PASS: six CSVs and six ledgers byte-identical; 16 open issues; five unknown owner amounts.');print(sizes)
Path('.runs/gate4/completion-verification.json').write_text(json.dumps(dict(csvs_identical=6,ledgers_identical=6,open_issues=16,unknown_owners=5,sizes=sizes),indent=2)+'\n')
PY","max_output_tokens":700}));
text(await tools.write_stdin({session_id:11036,chars:"","yield_time_ms":1000,"max_output_tokens":500}));

text(await tools.exec_command({cmd:"python3 -B - <<'PY'
from pathlib import Path
import shutil
p=Path('skills/class-code-assistant/scripts/__pycache__')
if p.exists(): shutil.move(str(p),'.runs/gate4/completion-bytecode')
PY","max_output_tokens":500}));
